mapper.delete:
delete from ssm_analysis_tpl_ai_exec_log
where 1 = 1

    and analysis_tpl_id = #{analysisTplId}


    and analysis_mode = #{analysisMode}


    and exec_result = #{execResult}


    and created_by = #{createdBy}

mapper.select:
select run_log_id as runLogId, analysis_tpl_id as analysisTplId, analysis_mode as analysisMode, analysis_input as analysisInput, exec_result as execResult, error_msg as errorMsg, exec_duration as execDuration, created_by as createdBy, created_time as createdTime from ssm_analysis_tpl_ai_exec_log where 1 = 1
and analysis_tpl_id = #{analysisTplId}
and analysis_mode = #{analysisMode}
and exec_result = #{execResult}
and created_by = #{createdBy}
order by created_time desc
